import{z as E,x as c,o as i,c as p,q as l,j as o,D as t,d as a,s as n,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"writeback","description":"","frontmatter":{"title":"writeback","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/writeback.md","filePath":"cs/writeback.md","lastUpdated":1791413859000}'),h={name:"cs/writeback.md"};function f(m,e,A,B,u,b){const s=c("Mermaid");return i(),p("div",null,[e[2]||(e[2]=l('<h1 id="writeback" tabindex="-1">writeback <a class="header-anchor" href="#writeback" aria-label="Permalink to &quot;writeback&quot;">​</a></h1><div class="epigraph"><p>脏页不在每次 write 时落盘；后台按比例与老化把它们排成回写，平衡吞吐与崩溃窗口。</p><footer>—— 据 Silberschatz 对延迟写的讨论；Love 对 Linux 写回的整理</footer></div><p><a href="/cs/page-cache">上一课</a>把脏位置在页上。<a href="/cs/buffer-dirty">缓冲与脏页</a> 说回写可由定时器、压力或 fsync 触发。缺口是<strong>策略引擎</strong>：脏比例、过期时间、flusher 线程、以及与 <a href="/cs/memory-reclaim">内存回收</a> 抢同一套 LRU 时谁先写。不是磁盘电梯——那是更后的块层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写回太勤，随机小写变成同步盘；太懒，崩溃窗口大，且回收时才发现全是脏页、分配卡死。缺口：维护脏页数量与阈值（如脏占内存比例）；超过后台阈值则 flusher 写；超过限制阈值则写者自己同步写（dirty throttling）。按 inode 或按 bdi（backing device）排队，避免一个文件饿死其他设备。</p><p><span class="marginnote">数字实例：限制阈值设为脏页占内存 20% 时——写到 19% 仍是 flusher 在后台慢慢刷；一越过 20%，每个 write 都被拖住同步清脏。后台阈值管吞吐、限制阈值管生死，两条线各司其职。</span></p><p>本课不把每版 <code>dirty_ratio</code> 的默认整数当考纲。</p><p><span class="marginnote">老化：页脏了多久。老脏页优先，减少「永远不刷的冷脏页」。laptop 模式可把回写攒成突发以让盘休眠。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>write</code> 只改页 Cache 并记账。kupdate/flusher：选过期或超额的 inode，调用 <a href="/cs/vfs">VFS</a> 的 <code>writepages</code>。回收路径上若碰到脏文件页，先加入回写再等完成或换一个牺牲。与 swap 写回并列但目标不同：这里写文件，不是槽。完成中断后清脏位。</p><p><span class="marginnote">术语翻译：writepages 就是 VFS 递给文件系统的一句「把这个 inode 的脏页批量写下去」——FS 负责按磁盘顺序把页排好交给块层。flusher 挑的是 inode 整体，不是一页一页零敲。</span></p>',11)),(i(),o(d,null,{default:t(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WRITE%5B%22write%20%E6%A0%87%E8%84%8F%22%5D%20--%3E%20RATIO%5B%22%E8%84%8F%E6%AF%94%E4%BE%8B%22%5D%0A%20%20RATIO%20--%3E%20BG%5B%22%E5%90%8E%E5%8F%B0%20flusher%22%5D%0A%20%20RATIO%20--%3E%20THR%5B%22%E8%BF%87%E9%99%90%E5%88%99%E5%86%99%E8%80%85%E8%8A%82%E6%B5%81%22%5D%0A%20%20BG%20--%3E%20DEV%5B%22writepages%20%E5%88%B0%E5%9D%97%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[a("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,[a("writeback 把延迟写收成可调的控制环，让 "),r("a",{href:"/cs/scheduling-metrics"},"调度"),a(" 看到的 I/O 等待成批出现而不是每次 "),r("code",null,"write"),a("。它不提供 "),r("code",null,"write"),a(" 返回即持久——那是下一课 fsync。崩溃时未刷的脏页丢失，正是窗口的含义。不要把组提交的数据库日志提前写进本课；文件系统日志在更后。")],-1)),e[5]||(e[5]=r("p",null,"老化如何决定谁先落盘：",-1)),(i(),o(d,null,{default:t(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E9%A1%B5%20A%EF%BC%9A%E5%88%9A%E6%A0%87%E8%84%8F%200%20%E7%A7%92%22%5D%20--%3E%20AGE%5B%22%E8%80%81%E5%8C%96%E8%AE%A1%E6%97%B6%22%5D%0A%20%20P2%5B%22%E9%A1%B5%20B%EF%BC%9A%E8%84%8F%E4%BA%86%2030%20%E7%A7%92%22%5D%20--%3E%20AGE%0A%20%20AGE%20--%3E%20PICK%5B%22%E4%BC%98%E5%85%88%E5%86%99%E6%9C%80%E8%80%81%E7%9A%84%E8%84%8F%E9%A1%B5%22%5D%0A%20%20PICK%20--%3E%20W1%5B%22B%20%E5%85%88%E8%90%BD%E7%9B%98%22%5D%0A%20%20PICK%20--%3E%20W2%5B%22A%20%E9%9A%8F%E4%B8%8B%E4%B8%80%E6%89%B9%E5%86%99%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<p><span class="marginnote">常见误区：以为 write 返回数据就安全了。它只保证进了页 Cache 并记上账；掉电丢的正是没刷的那部分——这就是「崩溃窗口」的本义。要「返回即持久」，必须显式 fsync，那是下一课的事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cgroup 写回带宽限制的全文。不保证 SSD 上「老化」仍有机械盘那种意义，但节流仍防写爆。下一课用户要一条系统调用等待「与此文件相关的脏页到达稳定介质」。</p><p>后课默认：回写是尽力的、异步的。显式持久是 fsync。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>flusher 按脏比例与老化写回页 Cache。</li><li>过限则写者阻塞，避免内存被脏页填满。</li><li>单文件持久等待是 fsync 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const k=E(h,[["render",f]]);export{_ as __pageData,k as default};
